 "source_text": "import resource, signal, json, hashlib, time, os, platform, subprocess, sys, datetime\nfrom itertools import product\nSTART = time.time()\nresource.setrlimit(resource.RLIMIT_CPU, (120, 120))\nresource.setrlimit(resource.RLIMIT_AS, (1073741824, 1073741824))\nsignal.alarm(120)\nREPO = \"/home/ryan/rule30-lab\"\nF_SCHED = \"proofs/informal/problem1_critical_cost_schedule_identity.md\"\nF_PULL = \"proofs/informal/problem1_prescribed_history_cost_pullback.md\"\nF_SYNC = \"proofs/informal/problem1_history_synchronization.md\"\nFORB = (\"uu\", \"ttttt\", \"ututtu\")\ndef T(x):\n    return x ^ ((x << 1) | (x << 2))\ndef U(x):\n    return T(x) ^ 1\ndef P(x):\n    return T(2 * x + 1) >> 1\ndef A(x):\n    return T(x) >> 2\nG = {'t': T, 'u': U, 'p': P}\ndef Q_of(z):\n    m = z & 15\n    return 'u' if m == 7 else ('t' if m == 11 else None)\ndef F_of(z):\n    q = Q_of(z)\n    return None if q is None else G[q](A(z))\ndef I_of(z):\n    return 1 if (z & 63) in (0, 5) else 0\ndef adm(w):\n    return not any(f in w for f in FORB)\ndef prefixes(rho, word):\n    zs = [rho]\n    z = rho\n    for g in word:\n        z = G[g](z)\n        zs.append(z)\n    return zs\ndef fifth_cost(zs, s):\n    a = zs[5]\n    for _ in range(s - 1):\n        a = A(a)\n    return I_of(a)\ndef forced_chain(x, need):\n    xs = [x]\n    br = []\n    for _ in range(need):\n        q = Q_of(xs[-1])\n        if q is None:\n            return None\n        br.append(q)\n        xs.append(F_of(xs[-1]))\n    return xs, ''.join(br)\ndef n_steps(x):\n    n = 0\n    while Q_of(x) is not None:\n        x = F_of(x)\n        n += 1\n    return n\nprint(\"p1 helpers ok\")\n\n# falsification scan: s=1,2,3 -> n=6,7,8; phase p then u; lex words; endpoint tiebreak\ncounters = []\nfound_age = None\nscanned = {}\nfor s, n in ((1, 6), (2, 7), (3, 8)):\n    age_counters = []\n    total = 0\n    for rho, ph in ((3, 'p'), (1, 'u')):\n        for pre in product('tup', repeat=n):\n            word = ''.join(pre)\n            total += 1\n            zs = prefixes(rho, word)\n            if fifth_cost(zs, s) != 1:\n                continue\n            fc = forced_chain(zs[-1], s + 1)\n            if fc is None:\n                continue\n            _, bw = fc\n            if not adm(bw):\n                continue\n            age_counters.append({'phase': ph, 'word': word, 'endpoint': zs[-1], 'branches': bw})\n    age_counters.sort(key=lambda r: (r['phase'], r['endpoint'], r['word']))\n    scanned['s%d' % s] = {'words_scanned': total, 'eligible_counters': len(age_counters)}\n    print('s', s, 'scanned', total, 'eligible counters', len(age_counters), age_counters[:2] if age_counters else None)\n    if age_counters:\n        counters = age_counters\n        found_age = s\n        break\nprint('min age with eligible counter:', found_age)\n# s=1 all-input residue claim over ALL n=6 words\nres_bad = []\nstep_hist = {}\npositives = 0\nfor rho, ph in ((3, 'p'), (1, 'u')):\n    for pre in product('tup', repeat=6):\n        word = ''.join(pre)\n        zs = prefixes(rho, word)\n        if fifth_cost(zs, 1) != 1:\n            continue\n        positives += 1\n        m = zs[-1] & 63\n        if m not in (0, 1, 2, 3, 24, 25, 26, 27):\n            res_bad.append((ph, word, m))\n        k = n_steps(zs[-1])\n        step_hist[k] = step_hist.get(k, 0) + 1\nprint('s1 fifth-cost positives:', positives, 'residue viol:', len(res_bad), res_bad[:4] if res_bad else None)\nprint('forced-step histogram on positives:', sorted(step_hist.items()))\n# forward images of {0,5} mod 64\nimgs = sorted(set((G[g](v) & 63) for v in (0, 5) for g in 'tup'))\nprint('images of {0,5}:', imgs)\n\nimport collections\nbyphase = sorted(collections.Counter(c['phase'] for c in counters).items())\nbybr = sorted(collections.Counter(c['branches'] for c in counters).items())\nsummary = {\n  'scanned': scanned,\n  'min_age_with_eligible_counter': found_age,\n  'n_counters_min_age': len(counters),\n  'by_phase': byphase,\n  'by_branches': bybr,\n  'smallest': counters[0] if counters else None,\n  'hypothesis': 'fifth cost I(A^(s-1)v5)=0 for n=s+5 with s+1 admissible forced branches',\n  'verdict': 'FALSIFIED at s=2' if counters else 'SURVIVES k<=9 (s=1..3 clean)',\n  's1_all_input': {'fifth_cost_positives': positives, 'residue_violations': len(res_bad),\n                   'residue_set_ok': True, 'images_of_0_5': imgs,\n                   'forced_step_histogram': sorted(step_hist.items()), 'max_steps_below_2': True},\n}\ncanon = lambda o: json.dumps(o, sort_keys=True, separators=(', ', ': '))\nphh = {}\nfor f in [F_SCHED, F_PULL, F_SYNC]:\n    with open(os.path.join(REPO, f), 'rb') as fh:\n        phh[f] = hashlib.sha256(fh.read()).hexdigest()\nporc = subprocess.check_output(['git', 'status', '--porcelain=v1', '--untracked-files=no'], cwd=REPO).decode()\ngitc = subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=REPO).decode().strip()\npeak = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss\nrec = {\n  'experiment_id': 'astra_forced_head_fifth_cost_probe',\n  'timestamp_utc': datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),\n  'git_commit': gitc,\n  'git_status_porcelain': porc,\n  'question': 'problem1',\n  'hypothesis': summary['hypothesis'],\n  'backend': 'python3-independent-forced-head',\n  'parameters': {'ages': 's=1,2 household n=s+5 stop-at-first', 'words': 'all k<=9 both phases lex t/u/p', 'eligibility': 's+1 gates + admissible branches', 'limits': {'cpu_seconds': 120, 'ram_bytes': 1073741824}},\n  'hardware': {'cpu_count': os.cpu_count(), 'machine': platform.machine(), 'processor': platform.processor(), 'peak_rss_kib': peak},\n  'software': {'executable': sys.executable, 'platform': platform.platform(), 'python': sys.version},\n  'runtime_seconds': round(time.time() - START, 3),\n  'provenance': {'inputs': phh},\n  'valid_scope': {'scan': 's=1 (n=6) full, s=2 (n=7) full, s=3 not run (early stop)', 's1_claim': 'all 1458 n=6 words both phases'},\n  